def simplify_path(path: str) -> str:
    """
    Canonicalise an absolute Unix path.

    - Collapses repeated slashes.
    - Resolves '.' (current directory) and '..' (parent directory).
    - '...' and any other name are treated as normal path components.
    - Returns the path with no trailing slash, except for the root '/'.
    """
    stack: list[str] = []

    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return '/' + '/'.join(stack)
